'use strict';
// Independent base58 implementation (BigInt) + Python bytes.__repr__ emulator.
const AL = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const IDX = new Map([...AL].map((c, i) => [c, BigInt(i)]));

function b58encode(buf) {
  let nz = 0;
  while (nz < buf.length && buf[nz] === 0) nz++;
  let acc = 0n;
  for (let i = nz; i < buf.length; i++) acc = acc * 256n + BigInt(buf[i]);
  let out = '';
  while (acc > 0n) { out = AL[Number(acc % 58n)] + out; acc /= 58n; }
  return '1'.repeat(nz) + out;   // default_one=False => empty for 0
}

function b58decode(str) {
  // caller must have already rstripped
  let origlen = str.length;
  let s = str.replace(/^1+/, '');
  let newlen = s.length;
  let acc = 0n;
  for (const ch of s) {
    const d = IDX.get(ch);
    if (d === undefined) throw new Error('Invalid character ' + ch);
    acc = acc * 58n + d;
  }
  const bytes = [];
  while (acc > 0n) { bytes.unshift(Number(acc & 255n)); acc >>= 8n; }
  return Buffer.from([...Array(origlen - newlen).fill(0), ...bytes]);
}

// Python repr(bytes)
function pyrepr(buf) {
  const hasSq = buf.includes(0x27), hasDq = buf.includes(0x22);
  const q = (hasSq && !hasDq) ? '"' : "'";
  let out = 'b' + q;
  for (const b of buf) {
    if (b === 0x5c) out += '\\\\';
    else if (b === 0x09) out += '\\t';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b === q.charCodeAt(0)) out += '\\' + q;
    else if (b < 0x20 || b >= 0x7f) out += '\\x' + b.toString(16).padStart(2, '0');
    else out += String.fromCharCode(b);
  }
  return out + q;
}
module.exports = { AL, b58encode, b58decode, pyrepr };

